<script>
$(function(){var root=$('#finance-dashboard'),url=function(s){return root.data('url').replace('__section__',s);},money=function(v){return Number(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});},count=function(v){return Number(v||0).toLocaleString('th-TH');},chart;function load(section,done,error){$.getJSON(url(section)).done(done).fail(function(xhr){if(error){error(xhr);}});}load('summary',function(d){$.each(d,function(k,v){root.find('[data-summary="'+k+'"]').text(v===null?'ไม่มีสิทธิ์':money(v));});},function(){root.find('[data-summary]').text('โหลดไม่สำเร็จ');});load('cash-trend',function(d){$('#finance-trend-state').remove();function draw(){if(chart){chart.destroy();}chart=new Chart(document.getElementById('finance-trend-chart'),{type:'bar',data:{labels:d.labels,datasets:[{label:'รับเงิน',data:d.receipts,backgroundColor:'#22a879',borderRadius:6},{label:'จ่ายเงิน',data:d.payments,backgroundColor:'#df5262',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{tooltip:{callbacks:{label:function(c){return c.dataset.label+': '+money(c.raw);}}}},scales:{y:{beginAtZero:true,ticks:{callback:money}}}}});}if(window.Chart){draw();}else{$.getScript('https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js').done(draw).fail(function(){$('#finance-trend-state').text('โหลดกราฟไม่สำเร็จ');});}},function(xhr){$('#finance-trend-state').text(xhr.status===403?'ไม่มีสิทธิ์':'โหลดไม่สำเร็จ');});load('aging',function(d){$.each(['ar','ap'],function(_,type){var box=root.find('[data-aging="'+type+'"]').empty(),values=d[type];if(!values){box.append($('<div>',{class:'col-12 text-secondary small',text:'ไม่มีสิทธิ์'}));return;}var labels={current_amount:'ปัจจุบัน',days_1_30:'1–30 วัน',days_31_60:'31–60 วัน',days_61_90:'61–90 วัน',days_over_90:'เกิน 90 วัน'};$.each(labels,function(k,label){box.append($('<div>',{class:'col-6 col-md'}).append($('<div>',{class:'border rounded p-2 h-100'}).append($('<div>',{class:'small text-secondary',text:label})).append($('<div>',{class:'fw-semibold mt-1',text:money(values[k])}))));});});},function(){root.find('[data-aging]').text('โหลดไม่สำเร็จ');});load('work',function(d){var labels={settlements_to_post:['รับ–จ่ายรอ Post','{{ route('finance.settlements.index') }}?status=APPROVED','cash'],vouchers_to_submit:['ใบขอจ่ายรอ Submit','{{ route('finance.payment-vouchers.index') }}?status=DRAFT','cash'],vouchers_to_approve:['ใบขอจ่ายรออนุมัติ','{{ route('finance.payment-vouchers.index') }}?status=SUBMITTED','cash'],vouchers_to_settle:['ใบขอจ่ายรอชำระ','{{ route('finance.payment-vouchers.index') }}?status=APPROVED','cash'],advance_outstanding:['เงินมัดจำ/ล่วงหน้าคงเหลือ','{{ route('finance.advance-deposits.index') }}','advance'],petty_cash_to_submit:['เงินสดย่อยรอ Submit','{{ route('finance.petty-cash.index') }}?status=DRAFT','cash'],petty_cash_to_approve:['เงินสดย่อยรออนุมัติ','{{ route('finance.petty-cash.index') }}?status=SUBMITTED','cash'],petty_cash_to_post:['เงินสดย่อยรอ Post','{{ route('finance.petty-cash.index') }}?status=APPROVED','cash'],petty_cash_topups_to_post:['เติมเงินสดย่อยรอ Post','{{ route('finance.petty-cash-top-ups.index') }}','advance'],petty_cash_clearings_to_post:['เคลียร์เงินสดย่อยรอ Post','{{ route('finance.petty-cash-clearings.index') }}','advance'],employee_advances_to_process:['เงินทดรองรอดำเนินการ','{{ route('finance.employee-advances.index') }}','advance'],employee_advance_clearings_to_process:['เคลียร์เงินทดรองรอดำเนินการ','{{ route('finance.employee-advance-clearings.index') }}','advance'],internal_transfers_to_post:['โอนเงินภายในรอ Post','{{ route('finance.internal-transfers.index') }}','advance']},any=false;root.find('.finance-work-items').empty();$.each(labels,function(k,item){if(typeof d[k]==='undefined'){return;}any=true;root.find('.finance-work-items[data-work-group="'+item[2]+'"]').append($('<a>',{href:item[1],class:'d-flex justify-content-between align-items-center text-reset text-decoration-none border-bottom pb-2'}).append($('<span>',{text:item[0]})).append($('<span>',{class:'badge app-badge-soft fs-6',text:count(d[k])})));});if(!any){root.find('.finance-work-items').html($('<div>',{class:'text-secondary small',text:'ไม่มีงานที่คุณมีสิทธิ์ติดตาม'}));}$.each(['employee_advances_due','employee_advances_due_soon','posting_exceptions','duplicate_receipts'],function(_,key){root.find('[data-control="'+key+'"]').text(typeof d[key]==='undefined'?'—':count(d[key]));});},function(){$('#finance-work').text('โหลดไม่สำเร็จ');root.find('[data-control]').text('โหลดไม่สำเร็จ');});var table=$('#finance-activities');if(table.length){var text=$.fn.dataTable.render.text();table.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:table.data('url'),pageLength:5,order:[[2,'desc']],buttons:[window.erpExcelButton(table)],columns:[{data:'document_number',name:'s.document_number',render:text.display},{data:'type_label',name:'s.document_type',render:text.display},{data:'date_label',name:'s.settlement_date',render:text.display},{data:'party_label',name:'p.code',render:text.display},{data:'bank_code',name:'b.code',render:text.display},{data:'net_amount',name:'s.net_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status',name:'s.status',render:text.display},{data:null,orderable:false,searchable:false,render:function(v,t,r){return t==='display'?'<a class="btn btn-sm btn-app-soft" href="'+text.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>':'';}}]}));}});
